arguments.command:
cd /tmp && mkdir -p stackalloc-test && cd stackalloc-test && cat > Program.cs << 'EOF'
using System;

Span<nint> nints = stackalloc nint[4];
nints[0] = 42;
nints[1] = nint.MaxValue;
Console.WriteLine($"nint span: [{nints[0]}, {nints[1]}], length={nints.Length}, sizeof(nint)={sizeof(nint)}");

Span<nuint> nuints = stackalloc nuint[4];
nuints[0] = 100;
nuints[1] = nuint.MaxValue;
Console.WriteLine($"nuint span: [{nuints[0]}, {nuints[1]}], length={nuints.Length}, sizeof(nuint)={sizeof(nuint)}");
EOF
cat > stackalloc-test.csproj << 'EOF'
<Project Sdk="Microsoft.NET.Sdk">
  <PropertyGroup>
    <OutputType>Exe</OutputType>
    <TargetFramework>net8.0</TargetFramework>
    <AllowUnsafeBlocks>true</AllowUnsafeBlocks>
  </PropertyGroup>
</Project>
EOF
dotnet run 2>&1

